// Die KI-Einschaetzung wird hier normalisiert und gegengeprueft.
// Warum ein zweiter, regelbasierter Notfall-Check: Ein Wasserschaden darf nicht
// deshalb als Regeltermin durchrutschen, weil das Modell den Satz anders gewichtet
// hat. Stichworte schlagen die KI — im Zweifel lieber ein Anruf zu viel.
const NOTFALL_STICHWORTE = [
  'wasserschaden', 'rohrbruch', 'wasser laeuft', 'wasser läuft', 'ueberschwemm', 'überschwemm',
  'gasgeruch', 'gas riecht', 'brandgeruch', 'es qualmt', 'kurzschluss', 'stromausfall',
  'heizungsausfall', 'heizung ausgefallen', 'heizung faellt aus', 'heizung fällt aus',
  'keine heizung', 'kein warmwasser', 'kein strom', 'notfall', 'dringend heute'
];
const GEWERKE = ['Heizung', 'Sanitaer', 'Elektro', 'Dach', 'Fenster', 'Maler', 'Sonstiges'];

const formular = $('Kundenanfrage empfangen').first().json;
const freitext = String(formular['Worum geht es?'] || '').toLowerCase();

const raus = [];
for (const eintrag of $input.all()) {
  const k = eintrag.json.message?.content ?? eintrag.json;

  const stichwortTreffer = NOTFALL_STICHWORTE.filter((w) => freitext.includes(w));
  const kiNotfall = String(k.dringlichkeit || '').toLowerCase() === 'notfall';
  const istNotfall = kiNotfall || stichwortTreffer.length > 0;

  // Gewerk auf die erlaubte Liste zwingen — sonst laufen Dauer-Zuordnung und
  // spaetere Auswertungen ins Leere.
  const gewerk = GEWERKE.includes(k.gewerk) ? k.gewerk : 'Sonstiges';

  raus.push({
    json: {
      kunde_name: formular['Name'] || '',
      kunde_mail: formular['E-Mail'] || '',
      kunde_telefon: formular['Telefon'] || '',
      adresse: `${formular['Strasse und Hausnummer'] || ''}, ${formular['PLZ und Ort'] || ''}`.trim(),
      ort: k.ort || formular['PLZ und Ort'] || null,
      plz: k.plz || null,
      gewerk,
      taetigkeit: k.taetigkeit || 'Nicht eingeordnet',
      hersteller_geraet: k.hersteller_geraet || null,
      zusammenfassung: k.zusammenfassung || freitext.slice(0, 200),
      wunschzeitraum: k.wunschzeitraum || formular['Wunschzeitraum'] || null,
      dringlichkeit: istNotfall ? 'notfall' : (k.dringlichkeit === 'dringend' ? 'dringend' : 'normal'),
      ist_notfall: istNotfall,
      notfall_grund: istNotfall ? (k.notfall_grund || stichwortTreffer.join(', ') || 'Stichwort im Anfragetext') : null,
      notfall_quelle: istNotfall ? (kiNotfall && stichwortTreffer.length ? 'KI und Stichwort' : (kiNotfall ? 'KI' : 'Stichwort')) : null,
      kontakt_vollstaendig: Boolean(formular['E-Mail'] && formular['Telefon']),
      eingegangen_am: new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }),
      originaltext: formular['Worum geht es?'] || ''
    }
  });
}
return raus;

// Aus den belegten Zeiten des Kalenders werden freie Slots gerechnet.
// Warum eine einzige freeBusy-Abfrage statt vieler Einzelabfragen: spart API-Kontingent
// und laesst sich hier komplett nachvollziehen. Faellt der Kalender aus, wird der
// Vorschlag bewusst NICHT geraten, sondern der Fall an die Disposition uebergeben.
const anfrage = $('Anfrage einordnen').first().json;

// Erfahrungswerte fuer die Einsatzdauer in Minuten — im Betrieb anpassen.
const DAUER = { Heizung: 120, Sanitaer: 90, Elektro: 90, Dach: 180, Fenster: 120, Maler: 240, Sonstiges: 90 };
const dauer = DAUER[anfrage.gewerk] ?? 90;

// Dringende Faelle bekommen ab morgen Termine, normale erst ab uebermorgen —
// ein Tag Vorlauf fuer Materialbeschaffung und Tourenplanung.
const vorlaufTage = anfrage.dringlichkeit === 'dringend' ? 1 : 2;

const antwort = $input.first().json ?? {};
const kalender = antwort.calendars ?? {};
const kalenderErreichbar = Object.keys(kalender).length > 0;

const belegt = [];
for (const eintrag of Object.values(kalender)) {
  for (const b of eintrag.busy ?? []) {
    belegt.push([new Date(b.start).getTime(), new Date(b.end).getTime()]);
  }
}

const zweiStellig = (n) => String(n).padStart(2, '0');
const datumDe = (d) => `${zweiStellig(d.getDate())}.${zweiStellig(d.getMonth() + 1)}.${d.getFullYear()}`;
const uhrzeit = (d) => `${zweiStellig(d.getHours())}:${zweiStellig(d.getMinutes())}`;
const WOCHENTAG = ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'];

const heute = new Date();
heute.setHours(0, 0, 0, 0);

const vorschlaege = [];
for (let tag = vorlaufTage; tag <= 21 && vorschlaege.length < 3; tag++) {
  const d = new Date(heute);
  d.setDate(d.getDate() + tag);
  const wt = d.getDay();
  if (wt === 0 || wt === 6) continue; // Regeltermine nur Mo–Fr

  for (const stunde of [8, 10, 13, 15]) {
    if (vorschlaege.length >= 3) break;
    const von = new Date(d);
    von.setHours(stunde, 0, 0, 0);
    const bis = new Date(von.getTime() + dauer * 60000);
    if (bis.getHours() > 17 || (bis.getHours() === 17 && bis.getMinutes() > 0)) continue; // Feierabend

    // Ueberschneidung mit einem belegten Block? Dann Slot verwerfen.
    const kollision = belegt.some(([bs, be]) => von.getTime() < be && bis.getTime() > bs);
    if (kollision) continue;

    // Pro Tag hoechstens ein Vorschlag, damit der Kunde echte Alternativen bekommt.
    if (vorschlaege.some((v) => v.datum === datumDe(von))) continue;

    vorschlaege.push({
      wochentag: WOCHENTAG[von.getDay()],
      datum: datumDe(von),
      von: uhrzeit(von),
      bis: uhrzeit(bis),
      start_iso: von.toISOString(),
      ende_iso: bis.toISOString()
    });
  }
}

const text = vorschlaege
  .map((v, i) => `${i + 1}) ${v.wochentag}, ${v.datum}, ${v.von}–${v.bis} Uhr`)
  .join('\n');

return [{
  json: {
    ...anfrage,
    kalender_erreichbar: kalenderErreichbar,
    belegte_bloecke: belegt.length,
    einsatzdauer_minuten: dauer,
    anzahl_vorschlaege: vorschlaege.length,
    vorschlaege,
    vorschlag_text: text,
    // Nur verschicken, wenn der Kalender wirklich geantwortet hat und mindestens
    // zwei Alternativen zusammenkommen — ein einzelner Termin ist kein Angebot.
    versandfaehig: kalenderErreichbar && vorschlaege.length >= 2 && Boolean(anfrage.kunde_mail)
  }
}];
